import { requireVendorSession } from "../../../../../lib/vendor-session";
import { submitVendorInvoice, vendorFinanceWorkspace } from "../../../../../lib/vendor-backoffice-service";
export async function POST(request:Request){try{const p=await requireVendorSession(request,true);const b=await request.json() as {procurementId?:unknown;invoiceNumber?:unknown;invoiceGrossMinor?:unknown};await submitVendorInvoice(p,{procurementId:typeof b.procurementId==="string"?b.procurementId:"",invoiceNumber:typeof b.invoiceNumber==="string"?b.invoiceNumber:"",invoiceGrossMinor:typeof b.invoiceGrossMinor==="number"?b.invoiceGrossMinor:Number.NaN});return Response.json(await vendorFinanceWorkspace(p));}catch(e){return Response.json({error:e instanceof Error?e.message:"invoice_submit_failed"},{status:400})}}
